package raft

import (
	"encoding/json"
	"fmt"
	"io"

	hclog "github.com/hashicorp/go-hclog"
	"sync"
	"testing"
	"time"
)

// termHookStore delays one chosen currentTerm write to model a slow store write
// that completes after a newer term has already been persisted by another goroutine.
type termHookStore struct {
	*InmemStore
	mu     sync.Mutex
	block  uint64
	before func(uint64)
	writes []uint64
}

func newTermHookStore() *termHookStore { return &termHookStore{InmemStore: NewInmemStore()} }

func (h *termHookStore) SetUint64(key []byte, val uint64) error {
	if string(key) == string(keyCurrentTerm) {
		h.mu.Lock()
		hook := h.before
		block := h.block
		h.mu.Unlock()
		if hook != nil && val == block {
			hook(val)
		}
		h.mu.Lock()
		h.writes = append(h.writes, val)
		h.mu.Unlock()
	}
	return h.InmemStore.SetUint64(key, val)
}

func (h *termHookStore) termWrites() []uint64 {
	h.mu.Lock()
	defer h.mu.Unlock()
	return append([]uint64(nil), h.writes...)
}

type recordFSM struct {
	mu      sync.Mutex
	applied map[uint64]string
}

func newRecordFSM() *recordFSM { return &recordFSM{applied: map[uint64]string{}} }

func (f *recordFSM) Apply(l *Log) interface{} {
	f.mu.Lock()
	f.applied[l.Index] = string(l.Data)
	f.mu.Unlock()
	return nil
}

func (f *recordFSM) Snapshot() (FSMSnapshot, error) { return &thSnapshot{}, nil }
func (f *recordFSM) Restore(io.ReadCloser) error    { return nil }

func (f *recordFSM) at(i uint64) (string, bool) {
	f.mu.Lock()
	defer f.mu.Unlock()
	v, ok := f.applied[i]
	return v, ok
}


type thSnapshot struct{}

func (s *thSnapshot) Persist(SnapshotSink) error { return nil }
func (s *thSnapshot) Release()                  {}

func thEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

func TestAssuranceHeartbeatTermRegression(t *testing.T) {
	store := newTermHookStore()
	fsm := newRecordFSM()
	snaps := NewInmemSnapshotStore()
	addr, trans := NewInmemTransport("F")
	trans.Connect(addr, trans) // self-directed RPCs still travel the real consumer queue

	conf := DefaultConfig()
	conf.LocalID = "F"
	conf.Logger = hclog.NewNullLogger()
	conf.ElectionTimeout = 30 * time.Second
	conf.HeartbeatTimeout = 30 * time.Second
	conf.LeaderLeaseTimeout = 30 * time.Second
	conf.CommitTimeout = time.Second

	cfg := Configuration{Servers: []Server{
		{Suffrage: Voter, ID: "F", Address: addr},
		{Suffrage: Voter, ID: "A", Address: "A"},
		{Suffrage: Voter, ID: "B", Address: "B"},
	}}
	if err := BootstrapCluster(conf, store, store, snaps, trans, cfg); err != nil {
		t.Fatalf("bootstrap: %v", err)
	}
	r, err := NewRaft(conf, fsm, store, store, snaps, trans)
	if err != nil {
		t.Fatalf("new raft: %v", err)
	}
	defer func() { _ = r.Shutdown().Error() }()

	send := func(req *AppendEntriesRequest) *AppendEntriesResponse {
		resp := &AppendEntriesResponse{}
		if err := trans.AppendEntries("A", addr, req, resp); err != nil {
			t.Fatalf("appendEntries rpc: %v", err)
		}
		return resp
	}
	leader := trans.EncodePeer("A", "A")

	// Baseline history: index 1 is the bootstrap configuration; commit 2 and 3 at term 2.
	if resp := send(&AppendEntriesRequest{RPCHeader: r.getRPCHeader(), Term: 2, Leader: leader,
		PrevLogEntry: 1, PrevLogTerm: 1, LeaderCommitIndex: 3,
		Entries: []*Log{{Index: 2, Term: 2, Type: LogCommand, Data: []byte("new2")}, {Index: 3, Term: 2, Type: LogCommand, Data: []byte("new3")}}}); !resp.Success {
		t.Fatalf("baseline append rejected")
	}
	time.Sleep(100 * time.Millisecond)

	// The stale leader's heartbeat carries term 3; hold its term write.
	blocked := make(chan struct{})
	release := make(chan struct{})
	var once sync.Once
	store.mu.Lock()
	store.block = 3
	store.before = func(uint64) {
		once.Do(func() { close(blocked) })
		<-release
	}
	store.mu.Unlock()

	hbDone := make(chan struct{})
	go func() {
		defer close(hbDone)
		rpc := RPC{Command: &AppendEntriesRequest{RPCHeader: r.getRPCHeader(), Term: 3, Leader: leader},
			RespChan: make(chan RPCResponse, 1)}
		r.processHeartbeat(rpc)
	}()
	select {
	case <-blocked:
	case <-time.After(5 * time.Second):
		t.Fatalf("heartbeat never reached its term write")
	}

	// Main thread adopts term 4 and applies index 4 from that leader.
	if resp := send(&AppendEntriesRequest{RPCHeader: r.getRPCHeader(), Term: 4, Leader: leader,
		PrevLogEntry: 3, PrevLogTerm: 2, LeaderCommitIndex: 4,
		Entries: []*Log{{Index: 4, Term: 4, Type: LogCommand, Data: []byte("new4")}}}); !resp.Success {
		t.Fatalf("term 4 append rejected: %+v", resp)
	}
	time.Sleep(100 * time.Millisecond)
	termAfterNewer := r.CurrentTerm()

	close(release)
	select {
	case <-hbDone:
	case <-time.After(5 * time.Second):
		t.Fatalf("heartbeat did not finish")
	}
	time.Sleep(100 * time.Millisecond)
	termAfterStale := r.CurrentTerm()
	persisted, _ := store.GetUint64(keyCurrentTerm)
	thEmit(t, map[string]interface{}{
		"event": "case_term_sequence",
		"case":  "heartbeat_term_regression",
	})
	thEmit(t, map[string]interface{}{
		"event":            "term_after_sequences",
		"case":             "heartbeat_term_regression",
		"fast_path_terms":  "3 then 4",
		"after_newer_term": termAfterNewer,
		"after_stale_term": termAfterStale,
		"persisted_term":   persisted,
		"term_writes":      fmt.Sprint(store.termWrites()),
		"term_decreased":   persisted < termAfterNewer,
	})

	// The stale term-3 leader now asserts its own history at index 4 and 5.
	ok := send(&AppendEntriesRequest{RPCHeader: r.getRPCHeader(), Term: 3, Leader: leader,
		PrevLogEntry: 3, PrevLogTerm: 2, LeaderCommitIndex: 5,
		Entries: []*Log{{Index: 4, Term: 3, Type: LogCommand, Data: []byte("stale4")}, {Index: 5, Term: 3, Type: LogCommand, Data: []byte("stale5")}}}).Success
	time.Sleep(200 * time.Millisecond)

	var l4, l5 Log
	e4 := r.logs.GetLog(4, &l4)
	e5 := r.logs.GetLog(5, &l5)
	v4, _ := fsm.at(4)
	v5, _ := fsm.at(5)
	thEmit(t, map[string]interface{}{
		"event": "case_stale_outcome",
		"case":  "heartbeat_term_regression",
	})
	thEmit(t, map[string]interface{}{
		"event":                   "stale_entries_outcome",
		"case":                    "heartbeat_term_regression",
		"stale_request_accepted":  ok,
		"log_index4_payload":      string(l4.Data),
		"log_index4_present":      e4 == nil,
		"fsm_index4_payload":      v4,
		"fsm_index5_payload":      v5,
		"log_index5_payload":      string(l5.Data),
		"log_index5_present":      e5 == nil,
		"applied_index":           r.AppliedIndex(),
		"commit_index":            r.CommitIndex(),
		"applied_entry_replaced":  v4 != string(l4.Data),
	})
	t.Logf("stale_accepted=%v log4=%q log5=%q fsm4=%q fsm5=%q commit=%d applied=%d",
		ok, l4.Data, l5.Data, v4, v5, r.CommitIndex(), r.AppliedIndex())
}

package raft

// Construction notes:
//   * Same follower setup as the forced-ordering probe, but no ordering hook:
//     the stable store optionally sleeps a random interval before persisting the
//     current term, modelling write latency jitter. Each attempt issues one
//     fast-path heartbeat carrying cur+1 concurrently with a term cur+2
//     AppendEntries through the real consumer path, then records whether the
//     persisted term ended below cur+2 (an inversion).

import (
	"encoding/json"
	"fmt"
	"io"
	"math/rand"
	"sync"
	"testing"
	"time"

	hclog "github.com/hashicorp/go-hclog"
)

type jitterStore struct {
	*InmemStore
	mu       sync.Mutex
	maxDelay time.Duration
	rnd      *rand.Rand
}

func newJitterStore(maxDelay time.Duration) *jitterStore {
	return &jitterStore{InmemStore: NewInmemStore(), maxDelay: maxDelay, rnd: rand.New(rand.NewSource(7))}
}

func (j *jitterStore) SetUint64(key []byte, val uint64) error {
	if string(key) == string(keyCurrentTerm) && j.maxDelay > 0 {
		j.mu.Lock()
		d := time.Duration(j.rnd.Int63n(int64(j.maxDelay)))
		j.mu.Unlock()
		time.Sleep(d)
	}
	return j.InmemStore.SetUint64(key, val)
}

type jitterFSM struct{ mu sync.Mutex }

func (f *jitterFSM) Apply(*Log) interface{}         { return nil }
func (f *jitterFSM) Snapshot() (FSMSnapshot, error) { return &jitterSnapshot{}, nil }
func (f *jitterFSM) Restore(io.ReadCloser) error    { return nil }

type jitterSnapshot struct{}

func (s *jitterSnapshot) Persist(SnapshotSink) error { return nil }
func (s *jitterSnapshot) Release()                  {}

func jEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

// jitterAttempts runs the concurrent term-write race attempts times and returns
// how many attempts ended with a persisted term below the higher request's term.
func jitterAttempts(t *testing.T, name string, maxDelay time.Duration, attempts int) (int, int) {
	t.Helper()
	store := newJitterStore(maxDelay)
	snaps := NewInmemSnapshotStore()
	addr, trans := NewInmemTransport("J")
	trans.Connect(addr, trans)

	conf := DefaultConfig()
	conf.LocalID = "J"
	conf.Logger = hclog.NewNullLogger()
	conf.LogLevel = "ERROR"
	conf.ElectionTimeout = 30 * time.Second
	conf.HeartbeatTimeout = 30 * time.Second
	conf.LeaderLeaseTimeout = 30 * time.Second
	conf.CommitTimeout = time.Second

	cfg := Configuration{Servers: []Server{
		{Suffrage: Voter, ID: "J", Address: addr},
		{Suffrage: Voter, ID: "A", Address: "A"},
		{Suffrage: Voter, ID: "B", Address: "B"},
	}}
	if err := BootstrapCluster(conf, store, store, snaps, trans, cfg); err != nil {
		t.Fatalf("bootstrap: %v", err)
	}
	r, err := NewRaft(conf, &jitterFSM{}, store, store, snaps, trans)
	if err != nil {
		t.Fatalf("new raft: %v", err)
	}
	defer func() { _ = r.Shutdown().Error() }()
	leader := trans.EncodePeer("A", "A")

	inversions := 0
	for i := 0; i < attempts; i++ {
		cur := r.CurrentTerm()
		last := r.LastIndex()

		// Fast-path heartbeat carrying an intermediate term, on its own goroutine.
		hbDone := make(chan struct{})
		go func(term uint64) {
			defer close(hbDone)
			rpc := RPC{Command: &AppendEntriesRequest{RPCHeader: r.getRPCHeader(), Term: term, Leader: leader},
				RespChan: make(chan RPCResponse, 1)}
			r.processHeartbeat(rpc)
		}(cur + 1)

		// Higher-term request through the consumer path.
		req := &AppendEntriesRequest{RPCHeader: r.getRPCHeader(), Term: cur + 2, Leader: leader,
			PrevLogEntry: last, LeaderCommitIndex: last + 1,
			Entries: []*Log{{Index: last + 1, Term: cur + 2, Type: LogCommand, Data: []byte("x")}}}
		if last == 0 {
			req.PrevLogTerm = 0
		} else {
			var prev Log
			if err := r.logs.GetLog(last, &prev); err == nil {
				req.PrevLogTerm = prev.Term
			}
		}
		resp := &AppendEntriesResponse{}
		if err := trans.AppendEntries("A", addr, req, resp); err != nil {
			t.Fatalf("appendEntries: %v", err)
		}
		<-hbDone

		if r.CurrentTerm() < cur+2 {
			inversions++
		}
		time.Sleep(time.Millisecond)
	}

	jEmit(t, map[string]interface{}{
		"event":        "jitter_case_" + name,
		"case":         name,
		"attempts":     attempts,
		"max_delay_ms": int(maxDelay / time.Millisecond),
		"final_term":   r.CurrentTerm(),
	})
	jEmit(t, map[string]interface{}{
		"event":            "jitter_result_" + name,
		"case":             name,
		"attempts":         attempts,
		"inversion_count":  inversions,
	})
	return inversions, attempts
}

func TestAssuranceHeartbeatTermWriteJitter(t *testing.T) {
	t.Run("control_no_delay", func(t *testing.T) {
		jitterAttempts(t, "control_no_delay", 0, 200)
	})
	t.Run("trigger_jittered_writes", func(t *testing.T) {
		jitterAttempts(t, "trigger_jittered_writes", 2*time.Millisecond, 200)
	})
}

package raft

// Construction notes:
//   * NewRaft() with RestoreCommittedLogs enabled replays committed log entries
//     by pushing commitTuple batches into r.fsmMutateCh, which is only drained
//     by runFSM. runFSM is started after NewRaft returns, so a replay that
//     produces more batches than the channel capacity cannot make progress.
//   * Cases below measure that boundary with (a) a log store seeded exactly at
//     and one entry past the boundary and (b) a real single-node cluster that
//     committed commands through the normal leader/commit/apply path before
//     shutdown, with and without a snapshot bounding the replay.

import (
	"encoding/json"
	"fmt"
	"io"
	"runtime"
	"strings"
	"sync"
	"testing"
	"time"

	hclog "github.com/hashicorp/go-hclog"
)

const (
	// Values taken from DefaultConfig(); records them in every case event so the
	// boundary arithmetic is inspectable.
	caMaxAppendEntries = 64
	caFSMBatchCapacity = 128
	caCommands         = 8300
)

type assuranceFSM struct {
	mu      sync.Mutex
	applied int
}

func (f *assuranceFSM) Apply(*Log) interface{} {
	f.mu.Lock()
	f.applied++
	f.mu.Unlock()
	return nil
}

func (f *assuranceFSM) Snapshot() (FSMSnapshot, error) { return &assuranceSnapshot{}, nil }

func (f *assuranceFSM) Restore(io.ReadCloser) error {
	f.mu.Lock()
	f.applied = 0
	f.mu.Unlock()
	return nil
}

func (f *assuranceFSM) count() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.applied
}

type assuranceSnapshot struct{}

func (s *assuranceSnapshot) Persist(SnapshotSink) error { return nil }
func (s *assuranceSnapshot) Release()                  {}

func caEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	// Direct stdout keeps every event in one stream; t.Log is only surfaced for
	// failing tests under go test -json without -v.
	fmt.Println("CA_EVENT " + string(data))
}

func caConfig(id string) *Config {
	conf := DefaultConfig()
	conf.LocalID = ServerID(id)
	conf.Logger = hclog.NewNullLogger()
	conf.LogLevel = "ERROR"
	conf.HeartbeatTimeout = 50 * time.Millisecond
	conf.ElectionTimeout = 50 * time.Millisecond
	conf.LeaderLeaseTimeout = 50 * time.Millisecond
	conf.CommitTimeout = 5 * time.Millisecond
	// Required in the producing run as well: the commit index is only staged in
	// the log store while this option is enabled.
	conf.RestoreCommittedLogs = true
	return conf
}

func caStackMatches() (processLogs int, restoreCommitted int) {
	buf := make([]byte, 1<<22)
	n := runtime.Stack(buf, true)
	text := string(buf[:n])
	return strings.Count(text, "(*Raft).processLogs("), strings.Count(text, "(*Raft).restoreFromCommittedLogs(")
}

type caStartResult struct {
	returned             bool
	elapsed              time.Duration
	err                  string
	fsmApplied           int
	newBlockedProcess    int
	newBlockedRestoreLog int
}

// caStartup calls NewRaft in a separate goroutine and bounds the wait. A caller
// that observes no return cannot call Shutdown: NewRaft has not handed back the
// *Raft, which is the only owner of shutdownCh.
func caStartup(conf *Config, fsm *assuranceFSM, store *InmemCommitTrackingStore,
	snaps SnapshotStore, addr ServerAddress, timeout time.Duration) caStartResult {
	baseLogs, baseRestore := caStackMatches()
	_, trans := NewInmemTransport(addr)
	done := make(chan error, 1)
	var raft *Raft
	start := time.Now()
	go func() {
		var err error
		raft, err = NewRaft(conf, fsm, store, store, snaps, trans)
		done <- err
	}()
	var result caStartResult
	select {
	case err := <-done:
		result.returned = true
		result.elapsed = time.Since(start)
		if err != nil {
			result.err = err.Error()
		} else {
			defer func() { _ = raft.Shutdown().Error() }()
		}
	case <-time.After(timeout):
		result.elapsed = time.Since(start)
		result.err = "no return within observation window"
	}
	result.fsmApplied = fsm.count()
	logs, restore := caStackMatches()
	result.newBlockedProcess = logs - baseLogs
	result.newBlockedRestoreLog = restore - baseRestore
	return result
}

func caEmitCase(t *testing.T, name, mode string, timeout time.Duration,
	entries, stagedCommit, lastLog, snapshotIndex uint64) {
	replay := uint64(0)
	if stagedCommit > snapshotIndex {
		replay = stagedCommit - snapshotIndex
	}
	caEmit(t, map[string]interface{}{
		"event":                  "startup_case_" + name,
		"case":                   name,
		"mode":                   mode,
		"restore_committed_logs": true,
		"max_append_entries":     caMaxAppendEntries,
		"fsm_batch_capacity":     caFSMBatchCapacity,
		"entries":                entries,
		"staged_commit_index":    stagedCommit,
		"last_log_index":         lastLog,
		"snapshot_index":         snapshotIndex,
		"replay_entries":         replay,
		"replay_batches":         (replay + caMaxAppendEntries - 1) / caMaxAppendEntries,
		"timeout_ms":             int(timeout / time.Millisecond),
	})
}

func caEmitResult(t *testing.T, name string, res caStartResult) {
	caEmit(t, map[string]interface{}{
		"event":                            "startup_result_" + name,
		"case":                             name,
		"returned":                         res.returned,
		"elapsed_ms":                       int(res.elapsed / time.Millisecond),
		"error":                            res.err,
		"fsm_applied_sampled":              res.fsmApplied,
		"new_goroutines_in_process_logs":   res.newBlockedProcess,
		"new_goroutines_in_restore_replay": res.newBlockedRestoreLog,
	})
}

func caSeededCase(t *testing.T, name string, entries uint64, timeout time.Duration) {
	store := NewInmemCommitTrackingStore()
	logs := make([]*Log, 0, entries)
	for i := uint64(1); i <= entries; i++ {
		logs = append(logs, &Log{Index: i, Term: 1, Type: LogCommand, Data: []byte("x")})
	}
	if err := store.StoreLogs(logs); err != nil {
		t.Fatalf("seed logs: %v", err)
	}
	if err := store.StageCommitIndex(entries); err != nil {
		t.Fatalf("stage commit index: %v", err)
	}
	lastLog, err := store.LastIndex()
	if err != nil {
		t.Fatalf("last index: %v", err)
	}
	caEmitCase(t, name, "seeded_commit_tracking_store", timeout, entries, entries, lastLog, 0)
	conf := caConfig("node1")
	res := caStartup(conf, &assuranceFSM{}, store, NewInmemSnapshotStore(), "node1", timeout)
	caEmitResult(t, name, res)
}

type caPrefix struct {
	store         *InmemCommitTrackingStore
	snaps         *InmemSnapshotStore
	stagedCommit  uint64
	lastLog       uint64
	snapshotIndex uint64
}

// caRealPrefix produces committed entries through a real single-node cluster and
// shuts it down, returning the retained stores.
func caRealPrefix(t *testing.T, commands int, takeSnapshot bool) caPrefix {
	store := NewInmemCommitTrackingStore()
	snaps := NewInmemSnapshotStore()
	conf := caConfig("node1")
	_, trans := NewInmemTransport("node1")
	configuration := Configuration{Servers: []Server{{Suffrage: Voter, ID: "node1", Address: trans.LocalAddr()}}}
	if err := BootstrapCluster(conf, store, store, snaps, trans, configuration); err != nil {
		t.Fatalf("bootstrap: %v", err)
	}
	r, err := NewRaft(conf, &assuranceFSM{}, store, store, snaps, trans)
	if err != nil {
		t.Fatalf("create producing raft: %v", err)
	}
	deadline := time.Now().Add(10 * time.Second)
	for r.Leader() == "" && time.Now().Before(deadline) {
		time.Sleep(2 * time.Millisecond)
	}
	if r.Leader() == "" {
		t.Fatalf("producing raft did not elect a leader")
	}
	var last ApplyFuture
	for i := 0; i < commands; i++ {
		last = r.Apply([]byte("x"), 5*time.Second)
	}
	if err := last.Error(); err != nil {
		t.Fatalf("apply through leader: %v", err)
	}
	if takeSnapshot {
		if err := r.Snapshot().Error(); err != nil {
			t.Fatalf("snapshot: %v", err)
		}
	}
	snapshotIndex := uint64(0)
	listed, err := snaps.List()
	if err != nil {
		t.Fatalf("list snapshots: %v", err)
	}
	if len(listed) > 0 {
		snapshotIndex = listed[0].Index
	}
	if err := r.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown producing raft: %v", err)
	}
	staged, err := store.GetCommitIndex()
	if err != nil {
		t.Fatalf("read staged commit index: %v", err)
	}
	lastLog, err := store.LastIndex()
	if err != nil {
		t.Fatalf("read last log index: %v", err)
	}
	return caPrefix{store: store, snaps: snaps, stagedCommit: staged, lastLog: lastLog, snapshotIndex: snapshotIndex}
}

func TestAssuranceRestoreCommittedLogsStartupReplay(t *testing.T) {
	// Controls run first so each trigger case reports newly blocked goroutines.
	t.Run("control_128_batches", func(t *testing.T) {
		caSeededCase(t, "control_128_batches", 8192, 20*time.Second)
	})
	t.Run("control_real_prefix_with_snapshot", func(t *testing.T) {
		prefix := caRealPrefix(t, caCommands, true)
		caEmitCase(t, "control_real_prefix_with_snapshot", "real_cluster_restart", 20*time.Second,
			caCommands, prefix.stagedCommit, prefix.lastLog, prefix.snapshotIndex)
		conf := caConfig("node1")
		res := caStartup(conf, &assuranceFSM{}, prefix.store, prefix.snaps, "node1", 20*time.Second)
		caEmitResult(t, "control_real_prefix_with_snapshot", res)
	})
	t.Run("trigger_129_batches", func(t *testing.T) {
		caSeededCase(t, "trigger_129_batches", 8193, 5*time.Second)
	})
	t.Run("trigger_real_prefix_no_snapshot", func(t *testing.T) {
		prefix := caRealPrefix(t, caCommands, false)
		caEmitCase(t, "trigger_real_prefix_no_snapshot", "real_cluster_restart", 5*time.Second,
			caCommands, prefix.stagedCommit, prefix.lastLog, prefix.snapshotIndex)
		conf := caConfig("node1")
		res := caStartup(conf, &assuranceFSM{}, prefix.store, prefix.snaps, "node1", 5*time.Second)
		caEmitResult(t, "trigger_real_prefix_no_snapshot", res)
	})
}

